      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not describe how exclusions are distinguished between cases where outcomes were not measured versus where outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "To explore the observed heterogeneity, we conducted prespecified subgroup analyses to evaluate the effect of high versus low risk of bias on model performance and relied on studies at low risk of bias if a significant difference was observed.",
      "reason": "The evidence identifies subgroup “groups” used in analyses (high vs low risk of bias). However, it does not clearly specify groups used in each synthesis or link them to the comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_22",
      "quote": "Fourthly, our review excluded prognostic models solely evaluating composite outcomes, such as major adverse cardiovascular events, as our linked guideline focused on individual cardiovascular and kidney outcomes.",
      "reason": "A rationale is provided for a notable restriction on study eligibility (exclusion of prognostic models evaluating composite outcomes) with an explicit justification tied to the guideline focus."
    }
